AgentPolicyList.propTypes = {
  profileData: PropTypes.object,
  agentPolicyList: PropTypes.array.isRequired,
  agentPolicyListMetaData: PropTypes.object.isRequired,
  products: PropTypes.array
}

AgentPolicyList.defaultProps = {
  profileData: {},
  agentPolicyList: [],
  agentPolicyListMetaData: {},
  agentPolicyListMetaDataCore: {},
  products: []
}

export default connect(state => ({
  agentProviderListData: state.AgentProvider.agentProviderList,
  profileData: state.Auth.profile,
  agentPolicyList: state.Agent.agentPolicyList,
  branchList: state.AgentProduct.branchList,
  branchListMessage: state.AgentProduct.branchListMessage,
  agentPolicyListMetaData: state.Agent.metadata,
  agentPolicyListMetaDataCore: state.Agent.metaDataCore,
  agentProductList: state.AgentProduct.agentProductList,
  isAgentInsuranceProvider: state.Auth.isAgentInsuranceProvider,
  agentPolicyListLoading: state.Loading.GET_AGENT_INSURANCE_LIST,
  agentPolicyListError: state.Error.GET_AGENT_INSURANCE_LIST
}), {
  getAgentInsuranceList,
  getAgentProviderList,
  getAgentProductList,
  getBranchList,
  resetAgentRedux
})(AgentPolicyList)
