import React, { useCallback } from 'react'
import Button from '../../../uielements/button'
import { FilterMultipleSelectOptionStyle } from './index.style'
import { Select } from 'antd'
import PropTypes from 'prop-types'
const { Option } = Select

function MultiSelectFilter (props) {
  const { onInputChange, onSearch, idIdentifier, searchText, optionData, renderOption } = props

  const renderStatus = useCallback(status => {
    return (
      status.map(val => (
        <Option key={val.code} value={val.code}>
          {val.name}
        </Option>
      ))
    )
  }, [])

  return (
    <FilterMultipleSelectOptionStyle>
      <Select
        mode='multiple'
        id={idIdentifier}
        onChange={onInputChange}
        style={{ width: '155px' }}
      >
        {renderOption ? renderOption(optionData) : renderStatus(optionData)}
      </Select>
      <Button type='primary' onClick={onSearch} disabled={searchText === undefined || searchText === ''} style={{ marginTop: '10px' }}>
        Search
      </Button>
    </FilterMultipleSelectOptionStyle>
  )
}

MultiSelectFilter.propTypes = {
  onSearch: PropTypes.func,
  onInputChange: PropTypes.func,
  idIdentifier: PropTypes.string,
  searchText: PropTypes.string,
  optionData: PropTypes.arrayOf(PropTypes.object),
  renderOption: PropTypes.func
}

export default MultiSelectFilter
